// The deployed worker (wrangler.jsonc `main`): venue images (`/media/…`) and the link preview's
// video are answered here, before Next, so one costs a cache lookup or an asset read; every other
// request is the OpenNext app, whose pages get the video card for the crawlers that play it.
// @ts-expect-error `.open-next/worker.js` is generated by `opennextjs-cloudflare build`.
import app from "./.open-next/worker.js";
import { PREVIEW_VIDEO } from "./src/lib/link-preview";
import { servePreviewVideo, withPlayerCard } from "./src/lib/link-preview-worker";
import { serveVenueImage } from "./src/lib/markets/venue-image-proxy";

export default {
  async fetch(request, env, ctx) {
    const { pathname } = new URL(request.url);
    if (pathname.startsWith("/media/")) return serveVenueImage(request, ctx);
    if (pathname === PREVIEW_VIDEO.path && env.ASSETS)
      return servePreviewVideo(request, env.ASSETS);
    return withPlayerCard(request, await app.fetch(request, env, ctx));
  },
} satisfies ExportedHandler<CloudflareEnv>;
